import React, { useState, useEffect } from "react";
import "../styles/CreateArticlesAdmin.css";

export default function CreateArticlePage() {
  const [mode, setMode] = useState("standard"); // standard / channel
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [excerpt, setExcerpt] = useState("");
  const [isPremium, setIsPremium] = useState(false);
  const [category, setCategory] = useState("sport");
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState("");
  const [image, setImage] = useState(null);
  const [message, setMessage] = useState("");
  const token = localStorage.getItem("token");

  useEffect(() => {
    fetch("http://127.0.0.1:8000/api/channels/")
      .then((res) => res.json())
      .then((data) => setChannels(data))
      .catch(() => setChannels([]));
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");

    const articleType = mode === "standard" ? "standard" : "interactive";

    const formData = new FormData();
    formData.append("title", title);
    formData.append("content", content);
    formData.append("excerpt", excerpt);
    formData.append("is_premium", isPremium);
    formData.append("type", articleType);

    if (articleType === "standard") {
      formData.append("category", category);
    } else if (articleType === "interactive") {
      formData.append("channel", selectedChannel);
    }

    if (image) {
      formData.append("image", image);
    }

    try {
      const res = await fetch("http://127.0.0.1:8000/api/articles/", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${token}`,
        },
        body: formData,
      });

      if (!res.ok) {
        const text = await res.text();
        throw new Error(text);
      }

      setMessage("✅ Статтю успішно створено!");
      setTitle("");
      setContent("");
      setExcerpt("");
      setIsPremium(false);
      setCategory("sport");
      setSelectedChannel("");
      setImage(null);
    } catch (err) {
      console.error("Помилка створення:", err);
      setMessage("❌ Не вдалося створити статтю");
    }
  };

  return (
    <div className="create-article-container">
      <h2>Створити статтю</h2>
      <form onSubmit={handleSubmit} className="create-article-form">
        <label>
          Тип статті:
          <select value={mode} onChange={(e) => setMode(e.target.value)}>
            <option value="standard">Звичайна стаття</option>
            <option value="channel">Стаття для каналу</option>
          </select>
        </label>

        <input
          type="text"
          placeholder="Заголовок"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          required
        />

        <textarea
          placeholder="Текст статті"
          value={content}
          onChange={(e) => setContent(e.target.value)}
          required
        />

        <textarea
          placeholder="Короткий опис"
          value={excerpt}
          onChange={(e) => setExcerpt(e.target.value)}
        />

        {mode === "standard" && (
          <>
            <label>
              Категорія:
              <select value={category} onChange={(e) => setCategory(e.target.value)}>
                <option value="sport">Спорт</option>
                <option value="fashion">Мода</option>
                <option value="News">Новини</option>
              </select>
            </label>
            <label>
              <input
                type="checkbox"
                checked={isPremium}
                onChange={(e) => setIsPremium(e.target.checked)}
              />
              Преміум
            </label>
          </>
        )}

        {mode === "channel" && (
          <label>
            Виберіть канал:
            <select value={selectedChannel} onChange={(e) => setSelectedChannel(e.target.value)}>
              <option value="">-- Оберіть канал --</option>
              {channels.map((ch) => (
                <option key={ch.id} value={ch.id}>
                  {ch.name}
                </option>
              ))}
            </select>
          </label>
        )}

        <label>
          Зображення:
          <input type="file" onChange={(e) => setImage(e.target.files[0])} />
        </label>

        <button type="submit">Створити</button>
        {message && <p>{message}</p>}
      </form>
    </div>
  );
}
